package cn.pi.dailyone;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.text.InputType;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.content.Context;import android.webkit.*;import android.widget.*;import org.json.JSONObject;
/** Owns the native sign-in view and one official authentication session. No password persistence. */
final class AuthController {
 interface Listener { void onFinished(boolean signedIn); }
 private final Activity activity;private final FrameLayout parent;private final String protocol;private final Listener listener;
 private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable tick=new Runnable(){public void run(){poll();}};
 private LinearLayout panel;private ScrollView form;private WebView authWeb;private EditText account,password;private TextView hint;private Button submit,retry,backToForm;private boolean open,foreground=true,ready,submitting,checking,clearing,cancelAfterClear,timedOut;private int generation;private long probeAt;private long started,sentAt;
 AuthController(Activity a,FrameLayout p,String js,Listener l){activity=a;parent=p;protocol=js;listener=l;}
 boolean isOpen(){return open;}
 void show(boolean switchAccount){if(open)return;open=true;
 // The editable fields are native and visible before any network request starts.
 panel=new LinearLayout(activity);panel.setOrientation(1);panel.setBackgroundColor(Color.rgb(245,247,250));parent.addView(panel,new FrameLayout.LayoutParams(-1,-1));
 LinearLayout top=new LinearLayout(activity);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(22),dp(14),dp(20),dp(8));TextView title=text(switchAccount?"切换力扣账号":"账号密码登录",22,0xFF263548);title.setTypeface(null,1);top.addView(title,new LinearLayout.LayoutParams(0,dp(48),1));Button cancel=button("取消",false);top.addView(cancel,new LinearLayout.LayoutParams(dp(58),dp(36)));cancel.setOnClickListener(v->close(true,false));panel.addView(top);
 TextView site=text("国内力扣 · leetcode.cn",12,0xFF8A98AA);site.setPadding(dp(24),0,dp(24),dp(14));panel.addView(site);
 FrameLayout body=new FrameLayout(activity);panel.addView(body,new LinearLayout.LayoutParams(-1,0,1));authWeb=new WebView(activity);WebSupport.configure(authWeb);authWeb.setBackgroundColor(0xFFF5F7FA);body.addView(authWeb,new FrameLayout.LayoutParams(-1,-1));
 form=new ScrollView(activity);form.setFillViewport(true);form.setBackgroundColor(0xFFF5F7FA);body.addView(form,new FrameLayout.LayoutParams(-1,-1));LinearLayout inputs=new LinearLayout(activity);inputs.setOrientation(1);inputs.setPadding(dp(24),dp(25),dp(24),dp(30));form.addView(inputs);
 inputs.addView(text("账号",13,0xFF63758C));account=input("手机号 / 邮箱",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);inputs.addView(account,fieldParams());TextView pl=text("密码",13,0xFF63758C);LinearLayout.LayoutParams labelLp=new LinearLayout.LayoutParams(-1,-2);labelLp.topMargin=dp(18);inputs.addView(pl,labelLp);password=input("请输入密码",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);inputs.addView(password,fieldParams());
 CheckBox show=new CheckBox(activity);show.setText("显示密码");show.setTextColor(0xFF8190A4);show.setTextSize(12);show.setOnCheckedChangeListener((b,checked)->{password.setInputType(InputType.TYPE_CLASS_TEXT|(checked?InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD:InputType.TYPE_TEXT_VARIATION_PASSWORD));password.setSelection(password.length());});inputs.addView(show);
 hint=text(switchAccount?"正在退出原账号，代码草稿会保留…":"正在连接官方登录服务，可先输入账号和密码…",12,0xFF8391A6);hint.setPadding(0,dp(8),0,dp(8));inputs.addView(hint);
 submit=button("登录",true);submit.setEnabled(false);LinearLayout.LayoutParams submitLp=new LinearLayout.LayoutParams(-1,dp(52));submitLp.topMargin=dp(14);inputs.addView(submit,submitLp);submit.setOnClickListener(v->send());password.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_DONE);password.setOnEditorActionListener((v,id,event)->{if(id==android.view.inputmethod.EditorInfo.IME_ACTION_DONE){send();return true;}return false;});
 retry=button("重新连接登录服务",false);LinearLayout.LayoutParams retryLp=new LinearLayout.LayoutParams(-1,dp(44));retryLp.topMargin=dp(13);inputs.addView(retry,retryLp);retry.setOnClickListener(v->{if(!clearing)load();});
 backToForm=button("返回账号密码输入",false);panel.addView(backToForm,new LinearLayout.LayoutParams(-1,dp(45)));backToForm.setVisibility(View.GONE);backToForm.setOnClickListener(v->{form.setVisibility(View.VISIBLE);backToForm.setVisibility(View.GONE);});
 authWeb.setWebViewClient(new WebViewClient(){
 @Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return WebSupport.route(activity,r.getUrl());}
 @Override public void onPageFinished(WebView w,String url){if(open)schedule();}
 @Override public void onReceivedError(WebView w,WebResourceRequest r,WebResourceError e){if(open&&r.isForMainFrame()){ready=false;submitting=false;showStatus("连接失败，请点击重新连接登录服务",true);update();}}
 });
 if(switchAccount){clearing=true;retry.setEnabled(false);CookieManager.getInstance().removeAllCookies(ok->{if(!open)return;CookieManager.getInstance().flush();clearing=false;if(cancelAfterClear){close(true,false);return;}retry.setEnabled(true);load();});}else load();
 }
 private void load(){if(!open||clearing)return;handler.removeCallbacks(tick);ready=false;checking=false;submitting=false;form.setVisibility(View.VISIBLE);backToForm.setVisibility(View.GONE);generation++;timedOut=false;started=SystemClock.elapsedRealtime();showStatus("正在连接官方登录服务，可先输入账号和密码…",false);update();authWeb.loadUrl("https://leetcode.cn/accounts/login/?next=%2Fproblemset%2F");schedule();}
 private void schedule(){handler.removeCallbacks(tick);if(open&&foreground)handler.postDelayed(tick,700);}
 private void poll(){if(!open||!foreground||clearing)return;if(checking){if(SystemClock.elapsedRealtime()-probeAt>4000)checking=false;schedule();return;}if(!WebSupport.official(authWeb)){schedule();return;}checking=true;probeAt=SystemClock.elapsedRealtime();final int epoch=generation;authWeb.evaluateJavascript(protocol,ignored->{if(!open||epoch!=generation)return;authWeb.evaluateJavascript("JSON.stringify(window.DailyOneAuth ? window.DailyOneAuth.inspect() : {})",result->{if(!open||epoch!=generation)return;checking=false;JSONObject state=WebSupport.decode(result);if(state.optBoolean("signedIn")){CookieManager.getInstance().flush();close(true,true);return;}ready=state.optBoolean("ready")&&!timedOut;String error=state.optString("error"),stage=state.optString("stage");if(stage.equals("verification")||stage.equals("otp")||stage.equals("verification-wall")){form.setVisibility(View.GONE);backToForm.setVisibility(View.VISIBLE);authWeb.evaluateJavascript("window.DailyOneAuth.showVerification()",null);}else if(!error.isEmpty()){submitting=false;showStatus(error,true);}else if(submitting&&SystemClock.elapsedRealtime()-sentAt>30000){submitting=false;timedOut=true;ready=false;showStatus("官方响应较慢，未确认登录成功；可重新连接后重试",true);}else if(!submitting&&!timedOut){if(ready)showStatus("账号密码仅用于当前官方登录，不保存密码",false);else if(SystemClock.elapsedRealtime()-started>25000)showStatus("官方表单尚未就绪，请点击重新连接登录服务",true);}update();schedule();});});}
 private void send(){if(!open||!ready||submitting)return;String name=account.getText().toString().trim(),secret=password.getText().toString();if(name.isEmpty()||secret.isEmpty()){showStatus("请输入账号和密码",true);return;}if(!WebSupport.official(authWeb)){showStatus("官方登录服务未就绪，请重新连接",true);return;}submitting=true;sentAt=SystemClock.elapsedRealtime();showStatus("正在登录，请稍候…",false);update();InputMethodManager im=(InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE);if(im!=null)im.hideSoftInputFromWindow(password.getWindowToken(),0);
 String js="JSON.stringify(window.DailyOneAuth ? window.DailyOneAuth.submit("+JSONObject.quote(name)+","+JSONObject.quote(secret)+") : {sent:false})";
 authWeb.evaluateJavascript(js,result->{if(!open)return;JSONObject r=WebSupport.decode(result);if(!r.optBoolean("sent")){submitting=false;showStatus(r.optString("error","登录服务尚未就绪，请重新连接"),true);update();}schedule();});}
 private void update(){if(submit==null)return;submit.setText(submitting?"正在登录…":"登录");submit.setEnabled(ready&&!submitting&&!clearing);account.setEnabled(!submitting);password.setEnabled(!submitting);retry.setEnabled(!clearing);}
 private void showStatus(String s,boolean error){hint.setText(s);hint.setTextColor(error?0xFFB4534B:0xFF8391A6);}
 void foreground(boolean value){foreground=value;if(!value)handler.removeCallbacks(tick);else schedule();}
 void close(boolean notify,boolean signedIn){if(!open)return;if(notify&&clearing){cancelAfterClear=true;showStatus("正在结束原账号会话…",false);return;}open=false;handler.removeCallbacks(tick);if(password!=null)password.setText("");if(account!=null)account.setText("");parent.removeView(panel);WebSupport.destroy(authWeb);authWeb=null;if(notify)listener.onFinished(signedIn);}
 private TextView text(String s,int size,int color){TextView t=new TextView(activity);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
 private EditText input(String hint,int type){EditText t=new EditText(activity);t.setHint(hint);t.setTextSize(16);t.setSingleLine(true);t.setInputType(type);t.setTextColor(0xFF27384D);t.setHintTextColor(0xFFA1ACBB);t.setPadding(dp(16),0,dp(16),0);t.setSaveEnabled(false);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(13));bg.setStroke(dp(1),0xFFDDE4ED);t.setBackground(bg);return t;}
 private Button button(String label,boolean primary){Button b=new Button(activity);b.setText(label);b.setTextSize(primary?16:12);b.setAllCaps(false);b.setTextColor(primary?Color.WHITE:0xFF6E819B);GradientDrawable bg=new GradientDrawable();bg.setColor(primary?0xFF304B6B:0xFFE9EEF5);bg.setCornerRadius(dp(12));b.setBackground(bg);return b;}
 private LinearLayout.LayoutParams fieldParams(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(54));p.topMargin=dp(9);return p;}
 private int dp(int n){return (int)(n*activity.getResources().getDisplayMetrics().density+.5f);}
}
